    const S1 = ST(), tk = "t:" + LG() + ":" + id; S1.tried[id] = {text: line.t, ts: Date.now(), pub: hang, feel, ph: tph ? tk : ""}; if (tph){ mPut(tk, {ph: tph}); MEDIA[tk] = {ph: tph, url: ""}; } S1.plans.forEach(x => { if (x.id === id) x.done = 1; }); save();
