  const spec = {bad: [["A", 4, "C", 2]], parts: [{tpl: CP.s1, py: CP.s1p, slots: {B: CP.B, A: CP.A}}, {tpl: CP.s2, py: CP.s2p, slots: {C: CP.C}}], W: CP.W, start: CP.start, ideas: CP.ideas, q: CP.q, ref: CP.ref};
