// ── 页面 ──
const SHELL = () => `<div class="lsx" data-nopy><div class="lsx-in">
  <div class="view" id="vFeed"><div class="scr" id="feedScr"><div class="hdr"><button class="x0" data-x0 aria-label="${esc(T("回去", "Back"))}">‹</button><h1 id="fTitle"></h1><button class="bag" id="bagBtn">🎒 <span id="bagN">0</span></button></div><div class="lede" id="fLede"></div><div class="topics" id="topics"></div><div id="plans"></div><div class="feed" id="feed"></div></div><button class="fab" id="fab"></button></div>
  <div class="view off" id="vDet"><div class="lbar"><button class="bk" data-back>‹</button><b id="dTitle"></b></div><div class="scr" id="detScr"></div></div>
  <div class="view off" id="vTry"><div class="lbar"><button class="bk" data-back>‹</button><b id="tTitle"></b></div><div class="scr" id="tryScr"></div></div>
  <div class="view off" id="vNew"><div class="lbar"><button class="bk" data-back>‹</button><b id="nTitle"></b></div><div class="scr" id="newScr"></div></div>
  <div class="sheetbg"></div><div class="sheet"></div><div class="notif"></div><div class="lstoast"></div></div></div>`;
